			19 => ['Have you ever used public transport for your commute?', '', 'Yes|No'],
			20 => ['Under what conditions would you use public transport for your commute?', 'Multiple answers possible', 'Shorter travel time|Greater comfort on public transport|More regular services|More frequent services|Transport available during my working hours|Transport near my home|Fewer connection difficulties|If I could have more information about public transport schedules/routes|The nearest public transport stop to the workplace entrance|More safety on public transport|If I could have an incentive for purchasing travel passes or a bicycle|If I could combine public transport with cycling|Other'],
			21 => ['If you could choose the type of incentive, which would you prefer?', '', '{"groups": [{"label": "Payroll instalment plan for travel pass costs", "options": ["No", "Yes"]}, {"label": "Discount on travel pass costs", "options": ["No", "Yes"]}, {"label": "Payroll instalment plan for the cost of a bicycle including electric-assist", "options": ["No", "Yes"]}, {"label": "Discount on the purchase of a bicycle including electric-assist", "options": ["No", "Yes"]}, {"label": "Free or discounted bike sharing subscription", "options": ["Yes", "No"]}, {"label": "Parking–public transport agreement (e.g. Park & Ride, bike station)", "options": ["No", "Yes"]}], "allowOther": true}'],
			22 => ['If new incentives were offered, would you be willing to use public transport?', '', 'Yes|No, because the stop is too far|No, because the route to reach the stop is not safe|No, because it is not possible to leave at the station/bring the bicycle on public transport'],
