			24 => ['Thinking about your HOME-WORK commute, which public transport do you use?', '', '{"groups": [{"label": "Bus/tram", "options": ["No", "N/A", "Yes"]}, {"label": "Metro", "options": ["No", "N/A", "Yes"]}, {"label": "Train", "options": ["Yes", "N/A", "No"]}, {"label": "Shuttle", "options": ["No", "N/A", "Yes"]}, {"label": "Other", "options": []}, {"label": "Car", "options": ["No", "N/A", "Yes"]}, {"label": "Motorbike", "options": ["No", "N/A", "Yes"]}, {"label": "Bicycle", "options": ["No", "N/A", "Yes"]}, {"label": "Kick scooter", "options": ["No", "N/A", "Yes"]}]}'],
			25 => ['If you answered "Bus", "Tram", "Train" or "Shuttle", specify the route', '', 'Bus GTT Collegno Fermi - Ferriera |Avigliana torino porta nuova sfm |train sfm3 tram 4|Train: SFM3'],
