		// ──── French translations (Questions) ────
		$questionsFr = [
			3 => ['Combien de kilomètres parcourez-vous en voiture/moto pour rejoindre votre lieu de travail/école (trajet aller uniquement) ?', 'Veuillez indiquer précisément le nombre de km parcourus en véhicule privé, en excluant les trajets effectués avec d\'autres moyens de transport, afin de calculer correctement les impacts environnementaux.', '<2 km|2,1-5 km|5,1-10 km|10,1-15 km|15,1-25 km|25,1-50 km|50,1-75 km|75,1-100 km|100,1-125 km|125,1-150 km|>150 km|Données non valides'],
			4 => ['Quel type d\'horaire de travail avez-vous', '', '2 postes (06:00 - 14:00 , 14:00 - 22:00)|3 postes  (06:00 - 14:00 , 14:00 - 22:00 , 22:00 - 06:00)|Journalier|Autre'],
			5 => ['À quelle heure partez-vous habituellement pour votre trajet ?', '', 'avant 6:30|entre 6:30 et 6:45|entre 6:45 et 7:00|entre 7:00 et 7:15|entre 7:15 et 7:30|entre 7:30 et 7:45|entre 7:45 et 8:00|entre 8:00 et 8:15|entre 8:15 et 8:30|entre 8:30 et 8:45|entre 8:45 et 9:00|après 9:00|travail posté|horaire en fonction des cours'],
			6 => ['Combien de minutes dure en moyenne votre trajet TRAVAIL-DOMICILE, pauses comprises', '', 'moins de 15 minutes|plus de 90 minutes|entre 15 et 30 minutes|entre 30 et 45 minutes|entre 45 et 60 minutes|entre 60 et 75 minutes|entre 75 et 90 minutes'],
			7 => ['À quelle heure sortez-vous habituellement lorsque vous terminez votre activité professionnelle pour rentrer chez vous ?', '', 'avant 14:00|de 14:00 à 14:30|de 14:30 à 15:00|de 15:00 à 15:30|de 15:30 à 16:00|de 16:00 à 16:30|de 16:30 à 17:00|de 17:00 à 17:30|de 17:30 à 18:00|de 18:00 à 18:30|de 18:30 à 19:00|après 19:00|travail posté|je sors toujours à des horaires différents'],
			8 => ['À quelle heure sortez-vous habituellement du travail le vendredi ?', '', 'avant 14:00|de 14:00 à 14:30|de 14:30 à 15:00|de 15:30 à 16:00|de 16:00 à 16:30|de 16:30 à 17:00|de 17:00 à 17:30|de 17:30 à 18:00|de 18:00 à 18:30|de 18:30 à 19:00|après 19:00'],
			9 => ['Pendant votre trajet, à l\'aller ou au retour, effectuez-vous d\'autres activités (ex. courses, achats, sport, accompagner les enfants à l\'école, etc.) ?', '', 'Oui, à l’aller|Oui, au retour|Oui, aussi bien à l\'aller qu\'au retour|Oui, seulement parfois|Non'],
			10 => ['Pour le trajet aller-retour, quel moyen de transport utilisez-vous principalement pendant les mois d\'hiver ?', 'Considérez le moyen de transport principal comme celui que vous utilisez pour parcourir le plus grand nombre de kilomètres', 'À pied|Bus/Tram|Métro|Voiture|Moto|Vélo|Trottinette|Taxi|Train|Service ferroviaire autres opérateurs (Trenord, Italo, Alta Velocità...)|Car sharing|Bike sharing|Moto en libre-service|Trottinette en libre-service|Navette d\'entreprise|Car pooling'],
			11 => ['Pour quelle raison utilisez-vous un moyen de transport privé ?', 'Plusieurs réponses possibles', 'Pendant le trajet domicile-travail, j\'effectue d\'autres activités (salle de sport, courses, etc.)|Je dois accompagner les enfants à l\'école |Utiliser un autre moyen de transport prendrait trop de temps|Pour des raisons de sécurité (manque de pistes cyclables, rues mal éclairées, meilleure sécurité sanitaire, etc.)|Moins de stress|Je n\'ai pas d\'alternative|Autre'],
			12 => ['Êtes-vous le conducteur du véhicule que vous utilisez pour votre trajet ?', '', 'Oui|Non'],
			13 => ['À quelle classe environnementale appartient votre voiture/moto ?', '', 'Euro 0|Euro 1|Euro 2|Euro 3|Euro 3 avec filtre à particules|Euro 4|Euro 4 avec filtre à particules|Euro 5|Euro 5 avec filtre à particules|Euro 6'],
			14 => ['Quelle est la cylindrée de votre voiture ?', '', 'Jusqu\'à 1200 cc|Jusqu\'à 1400 cc|Jusqu\'à 1600 cc|Jusqu\'à 1800 cc|Jusqu\'à 2000 cc|Plus de 2000 cc|Électrique'],
			15 => ['Quelle est la cylindrée de votre moto ou cyclomoteur ?', '', '50 cc|125 cc|Jusqu\'à 250 cc|Jusqu\'à 350 cc|Jusqu\'à 500 cc|Jusqu\'à 750 cc|Plus de 750 cc'],
			16 => ['Quel est le carburant de votre voiture ?', '', 'Essence|Diesel|Hybride|Électrique|GPL|Gaz naturel'],
			17 => ['Quel est le carburant de votre moto ou cyclomoteur ?', '', 'Essence|Électrique|Mélange deux-temps'],
			18 => ['Êtes-vous satisfait(e) des aspects suivants concernant l\'utilisation du véhicule motorisé privé pour vous rendre au travail ?', '', '{"groups": [{"label": "Coûts directs du déplacement (ex : carburant, stationnement, péages, …)", "options": ["Pas du tout satisfait", "Peu satisfait", "Assez satisfait", "Très satisfait"]}, {"label": "Temps de déplacement", "options": ["Pas du tout satisfait", "Peu satisfait", "Assez satisfait", "Très satisfait"]}, {"label": "Sécurité routière pendant le trajet", "options": ["Pas du tout satisfait", "Peu satisfait", "Assez satisfait", "Très satisfait"]}, {"label": "Sécurité contre le vol et le vandalisme", "options": ["Pas du tout satisfait", "Peu satisfait", "Assez satisfait", "Très satisfait"]}, {"label": "Système de stationnement", "options": ["Pas du tout satisfait", "Peu satisfait", "Assez satisfait", "Très satisfait"]}], "allowOther": false}'],
			19 => ['Vous est-il déjà arrivé d\'utiliser les transports en commun pour votre trajet ?', '', 'Oui|Non'],
			20 => ['À quelles conditions utiliseriez-vous les transports en commun pour effectuer votre trajet ?', 'Plusieurs réponses possibles', 'Durée de trajet plus courte|Plus de confort dans les transports en commun|Services plus réguliers|Services plus fréquents|Transports disponibles à mes horaires de travail|Transports à proximité de mon domicile|Moins de difficultés dans les correspondances|Si je pouvais avoir plus d’informations sur les horaires/parcours des transports en commun|L\'arrêt de transport en commun le plus proche de l\'entrée du site|Plus de sécurité dans les transports en commun|Si je pouvais disposer d’une aide pour l’achat de titres de transport ou d’un vélo|Si je pouvais combiner les transports en commun avec le vélo|Autre'],
			21 => ['Si vous pouviez choisir le type d\'incitation, laquelle préféreriez-vous ?', '', '{"groups": [{"label": "Échelonnement sur le salaire du coût des titres de transport", "options": ["Non", "Oui"]}, {"label": "Réduction sur le coût des titres de transport", "options": ["Non", "Oui"]}, {"label": "Échelonnement sur le salaire du coût d\'un vélo, y compris à assistance électrique", "options": ["Non", "Oui"]}, {"label": "Réduction sur l\'achat d\'un vélo, y compris à assistance électrique", "options": ["Non", "Oui"]}, {"label": "Abonnement vélo en libre-service offert ou à prix réduit", "options": ["Oui", "Non"]}, {"label": "Convention parking–transports en commun (ex : formule Park & Ride, vélostation)", "options": ["Non", "Oui"]}], "allowOther": true}'],
			22 => ['En cas de nouvelles incitations, seriez-vous disposé(e) à prendre les transports en commun ?', '', 'Oui|Non, car l\'arrêt est trop éloigné|Non, car le trajet pour atteindre l\'arrêt n\'est pas sûr|Non, car il n\'est pas possible de laisser à la gare/emporter le vélo dans les transports en commun'],
			23 => ['En pensant au trajet ALLER (domicile-travail), indiquez la SÉQUENCE de moyens de transport utilisés :', '', '{"groups": [{"label": "Moyen 1", "options": ["À pied", "Vélo", "Voiture", "Transport en commun", "Bateau", "Trottinette"]}, {"label": "Moyen 2", "options": ["À pied", "Vélo", "Voiture", "Transport en commun"]}, {"label": "Moyen 3", "options": ["À pied", "Vélo", "Voiture", "Transport en commun"]}, {"label": "Moyen 4", "options": ["À pied", "Vélo", "Voiture", "Transport en commun"]}]}'],
			24 => ['En pensant à votre trajet DOMICILE-TRAVAIL, quel transport en commun utilisez-vous ?', '', '{"groups": [{"label": "Bus/tram", "options": ["Non", "N/A", "Oui"]}, {"label": "Métro", "options": ["Non", "N/A", "Oui"]}, {"label": "Train", "options": ["Oui", "N/A", "Non"]}, {"label": "Navette", "options": ["Non", "N/A", "Oui"]}, {"label": "Autre", "options": []}, {"label": "Voiture", "options": ["Non", "N/A", "Oui"]}, {"label": "Moto", "options": ["Non", "N/A", "Oui"]}, {"label": "Vélo", "options": ["Non", "N/A", "Oui"]}, {"label": "Trottinette", "options": ["Non", "N/A", "Oui"]}]}'],
			25 => ['Si vous avez répondu « Bus », « Tram », « Train » ou « Navette », précisez le trajet', '', 'Bus GTT Collegno Fermi - Ferriera |Avigliana torino porta nuova sfm |train sfm3 tramway 4|Train : SFM3'],
			26 => ['Êtes-vous satisfait(e) des aspects suivants concernant le déplacement en transports en commun ?', '', 'label:Coûts de transport;options:Pas du tout satisfait,Peu satisfait,Plutôt satisfait,Très satisfait|label:Temps de trajet;options:Pas du tout satisfait,Peu satisfait,Plutôt satisfait,Très satisfait|label:Fréquence du service;options:Pas du tout satisfait,Peu satisfait,Plutôt satisfait,Très satisfait|label:Ponctualité du service;options:Pas du tout satisfait,Peu satisfait,Plutôt satisfait,Très satisfait|label:Nombre de correspondances;options:Pas du tout satisfait,Peu satisfait,Plutôt satisfait,Très satisfait|label:Praticité du trajet;options:Pas du tout satisfait,Peu satisfait,Plutôt satisfait,Très satisfait|label:Sécurité personnelle;options:Pas du tout satisfait,Peu satisfait,Plutôt satisfait,Très satisfait'],
			27 => ['Possédez-vous un abonnement aux transports en commun ?', '', 'Oui, annuel|Oui, mensuel|Oui, hebdomadaire|Achat de billets individuels |J\'utilise la carte de service'],
			28 => ['Seriez-vous disposé(e) à acheter un abonnement annuel aux transports en commun ?', '', 'Oui, si j’avais un échelonnement sur la fiche de paie |Oui, en cas de réduction sur l’abonnement|Oui, s’il y avait une convention parking-transports en commun (Parck&ride, velostazione)|Non'],
			29 => ['Indiquez votre niveau d\'appréciation des modalités organisationnelles suivantes', 'Indiquez votre niveau de satisfaction concernant les modalités organisationnelles suivantes', '{"groups": [{"label": "Classement 1", "options": ["Identification de points de rencontre (arrêts signalés par des poteaux, points de pause, etc.)", "Inscription à des services existants (applis, etc.)", "Organisation des groupes coordonnée par l\'entreprise"]}, {"label": "Classement 2", "options": ["Inscription à des services existants (applis, etc.)", "Organisation des groupes coordonnée par l\'entreprise", "Identification de points de rencontre (arrêts signalés par des poteaux, points de pause, etc.)"]}, {"label": "Classement 3", "options": ["Organisation des groupes coordonnée par l\'entreprise", "Inscription à des services existants (applis, etc.)", "Identification de points de rencontre (arrêts signalés par des poteaux, points de pause, etc.)"]}], "allowOther": false}'],
			30 => ['Comment seriez-vous disposé(e) à voyager dans un équipage de covoiturage ?', '', 'Aussi bien en tant que conducteur qu’en tant que passager|Uniquement en tant que conducteur|Uniquement en tant que passager'],
			31 => ['Quels jours de la semaine utilisez-vous ou utiliseriez-vous le covoiturage ?', 'Plusieurs réponses possibles', 'Lundi|Mardi|Mercredi|Jeudi|Vendredi|Samedi|Dimanche'],
			32 => ['De combien seriez-vous disposé(e) à augmenter la durée de votre trajet DOMICILE-TRAVAIL (en voiture seul) en utilisant le covoiturage ? Au maximum...', '', '10 minutes|15 minutes|5 minutes'],
			33 => ['Seriez-vous disposé(e) à vous inscrire à un service d\'autopartage ?', 'Plusieurs réponses possibles', 'Oui|Oui, s’il y avait une station à proximité de mon domicile/lieu de travail|Oui, si mon domicile/lieu de travail se trouvait à l\'intérieur de la zone opérationnelle du service |Je ne connais pas le service|Non'],
			35 => ['Quels moyens de transport utilisez-vous en été pour votre trajet ?', 'Plusieurs réponses possibles', 'Les mêmes que ceux que j\'utilise en hiver|À pied|Bus/tram|Métro GTT|Voiture|Moto/Scooter|Vélo|Trottinette|Taxi |Navette d\'entreprise|Service ferroviaire Trenitalia/GTT|Autre service ferroviaire (Trenord, Italo, Alta velocità, ...)|Car sharing|Bike sharing|Moto en libre-service|Car pooling'],
			36 => ['À quelles conditions vous rendriez-vous au travail à vélo ?', '', 'S’il y avait des itinéraires cyclables|Si des équipements utiles au déplacement à vélo étaient disponibles dans l’entreprise (râteliers, abris, vestiaires, douches)|S’il était possible d’arriver jusqu’au lieu de travail|S’il existait un parking d’échange adéquat avec les transports en commun (ex. en gare)|S’il existait un parking adéquat près du lieu de travail|Si je pouvais disposer d’une aide pour l’achat d’un vélo|Uniquement pendant les mois d’été|Jamais'],
			37 => ['Seriez-vous intéressé(e) à expérimenter des modalités de « travail agile »', 'Oui, mais seulement si l\'entreprise me fournissait les outils nécessaires. Oui, si l\'entreprise contribuait aux dépenses (ex. connexion internet, électricité, etc.). Non, jamais. Je serais intéressé(e) à travailler dans un espace de coworking près de chez moi', '{"groups": [{"label": "Autre", "options": ["mon travail ne le permet pas", "impossible en raison de la nature de mon travail", "je travaille déjà dans un espace de coworking", "je travaille au noir à durée indéterminée", "je le fais déjà", "J\'aimerais bien mais étant éducateur, c\'est malheureusement assez improbable que cela arrive", "non réalisable"]}], "allowOther": true}'],
			38 => ['Indiquez dans l\'espace ci-dessous vos propositions pour améliorer votre trajet quotidien', '', ''],
			39 => ['Lieu de travail', '', ''],
			40 => ['Sexe', '', 'Féminin|Masculin'],
			41 => ['Quel âge avez-vous ?', '', 'Entre 6 et 10|Entre 11 et 15|Entre 16 et 20|Entre 21 et 25|Entre 26 et 30|Entre 31 et 40|Entre 41 et 50|Entre 51 et 60|Plus de 60'],
			42 => ['Indiquez la province où vous résidez', '', 'AL|AT|BI|CN|NON|TO|VC|VCO|Autre (hors Piemonte)'],
			43 => ['Indiquez la commune où vous résidez', '', ''],
			44 => ['Indiquez l\'adresse de départ de votre trajet', 'Des doutes sur la vie privée ? Vous ne fournissez pas une information confidentielle. L\'adresse est une donnée dont votre employeur dispose déjà. Elle ne sera utilisée que pour les questions liées aux déplacements domicile-travail et ne sera pas communiquée à des tiers sauf sous forme anonyme.

Pour plus de précision, indiquez : rue, numéro, code postal, commune ; si vous préférez, indiquez seulement la commune', ''],
			166 => ['Combien de moyens de transport utilisez-vous pour vous rendre au travail ?', '', 'Un seul|Combinaison de deux ou plusieurs moyens'],
			168 => ['Pour quelle raison utilisez-vous les transports en commun pour votre trajet ?', 'Plusieurs réponses possibles', 'Sécurité|Vitesse|Rentabilité|Respect de l’environnement|Pendant le trajet, j\'effectue d\'autres activités|Utiliser un autre moyen de transport prendrait trop de temps|Je n\'ai pas d\'alternative '],
			169 => ['Seriez-vous disposé(e) à travailler depuis chez vous ?', '', 'Oui, tous les jours|Oui, 1 jour par semaine|Oui, 2 jours par semaine|Oui, 3 jours par semaine|Oui, 4 jours par semaine|Oui, 5 jours par semaine|Oui, si l\'entreprise me fournissait les outils|Oui, si l\'entreprise contribuait aux frais|Non, jamais'],
			170 => ['Seriez-vous disposé(e) à travailler dans un espace de coworking ?', 'Coworking : modèle de travail qui prévoit le partage des espaces d\'un environnement de travail, généralement un bureau, avec d\'autres personnes non employées par la même entreprise ou organisation', 'Oui, 1 jour par semaine|Oui, 2 jours par semaine|Oui, 3 jours par semaine|Oui, 4 jours par semaine|Oui, 5 jours par semaine|Non, jamais'],
			171 => ['Si vous pouviez combiner plusieurs moyens de transport dans un seul abonnement, lesquels choisiriez-vous ?', 'Plusieurs réponses possibles', 'Transport en commun (bus, tramway, métro urbain et périurbain)|Service ferroviaire|Taxi|Trottinette en libre-service|Moto en libre-service|Car sharing|Bike sharing|Location de voiture'],
			172 => ['Si un point de recharge pour véhicules électriques était disponible à votre destination, quel véhicule utiliseriez-vous ?', 'Plusieurs réponses possibles', 'Scooter|Trottinette|Vélo|Voiture|Aucune des précédentes'],
			174 => ['Évaluez l\'offre de transport en commun en général (transport public local, train, etc.)', '', 'Très mauvais|Suffisant|Passable|Bon|Excellent'],
			175 => ['Exprimez votre degré de satisfaction sur les aspects suivants des transports en commun', '', '{"groups": [{"label": "Confort", "options": ["Pas du tout satisfait", "Peu satisfait", "Assez satisfait", "Très satisfait"]}, {"label": "Ponctualité", "options": ["Pas du tout satisfait", "Peu satisfait", "Assez satisfait", "Très satisfait"]}, {"label": "Temps de trajet", "options": ["Pas du tout satisfait", "Peu satisfait", "Assez satisfait", "Très satisfait"]}, {"label": "Information", "options": ["Pas du tout satisfait", "Peu satisfait", "Assez satisfait", "Très satisfait"]}, {"label": "Proximité des arrêts", "options": ["Pas du tout satisfait", "Peu satisfait", "Assez satisfait", "Très satisfait"]}, {"label": "Tarifs", "options": ["Pas du tout satisfait", "Peu satisfait", "Assez satisfait", "Très satisfait"]}, {"label": "Fréquence", "options": ["Pas du tout satisfait", "Peu satisfait", "Assez satisfait", "Très satisfait"]}, {"label": "Sécurité", "options": ["Pas du tout satisfait", "Peu satisfait", "Assez satisfait", "Très satisfait"]}], "allowOther": false}'],
			176 => ['Seriez-vous disposé(e) à partager votre trajet avec quelqu\'un ?', 'Le covoiturage permet à un particulier, généralement via une plateforme, de mettre à disposition des places dans son véhicule pour partager son trajet (ou une partie de celui-ci) avec d\'autres personnes', 'Oui, je le fais déjà|Oui, si j’avais plus d’informations sur les économies et les avantages|Oui, si c’était plus avantageux économiquement ou si je pouvais quand même partager les coûts|Oui, si c’était pratique par rapport au point de départ|Oui, si c’était pratique par rapport au point d’arrivée|Oui, si le retour était garanti avec les mêmes modalités|Oui, si j’avais des informations sur le conducteur/passager|Non, jamais|Je ne connais pas les modalités de partage'],
			177 => ['Seriez-vous disposé(e) à utiliser le vélo pour votre trajet ?', '', 'Oui, uniquement celle dont je suis propriétaire|Oui, celle partagée (bike sharing)|Oui, s’il y avait des itinéraires cyclables sécurisés|Oui, si l\'entreprise disposait des équipements pour le déplacement à vélo (vestiaires et douches pour l\'hygiène personnelle,  avec possibilité de recharge pour ebike etc.)|Oui, s’il y avait un parking interne sécurisé|Oui, s’il y avait un parking d’échange adéquat avec les transports en commun (ex. en gare)|Oui, si je pouvais disposer d\'une prime ou d\'un remboursement pour l\'achat d\'un vélo|Oui, uniquement pendant les mois d\'été|Non'],
			178 => ['Seriez-vous disposé(e) à utiliser la trottinette ou le scooter pour votre trajet ?', 'Plusieurs réponses possibles', 'Oui, uniquement celui dont je suis propriétaire|Oui, celui partagé (trottinette/moto en partage)|Oui, si dans l’entreprise il y avait les équipements liés au déplacement (vestiaires et douches pour l’hygiène personnelle, avec possibilité éventuelle de recharge pour scooters/trottinettes électriques)|Oui, s’il y avait un parking interne sécurisé|Oui, si je pouvais disposer d\'une prime ou d\'un remboursement pour l\'achat du véhicule|Oui, si la couverture INAIL pour le déplacement était prévue|Oui, uniquement pendant les mois d\'été|Non'],
			179 => ['Combien de temps mettriez-vous pour effectuer le trajet en utilisant UNIQUEMENT les transports en commun ?', 'Ne pas considérer le trajet à pied s\'il est < 15 min (rendez-vous sur https://www.muoversiatorino.it/POS/-/nearyou ou https://www.muoversinpiemonte.it/ pour calculer les temps de déplacement)', 'Moins de 15 minutes|Entre 15 et 30 minutes|Entre 30 et 45 minutes|Entre 45 et 60 minutes|Entre 60 et 75 minutes|Entre 75 et 90 minutes|Plus de 90 minutes|Je n\'ai pas la possibilité de prendre un ou plusieurs transports en commun |Je ne sais pas'],
			180 => ['Combien dépensez-vous par mois pour votre trajet ?', 'Considérez les coûts de carburant, péages et stationnements', 'Moins de 30 Euro|Entre 30 et 50 Euro|Entre 50 et 80 Euro|Plus de 80 Euro|Les frais de déplacement domicile-travail me sont entièrement remboursés|J\'utilise uniquement la carte de service'],
			181 => ['À quelle distance se trouve l\'arrêt de transport en commun le plus proche du lieu de départ de votre trajet ?', 'Saisissez la distance en mètres', ''],
			183 => ['Recevez-vous une incitation (ex. bike to work, carburant, voiture de service, etc.) pour couvrir les frais de votre trajet ?', 'Plusieurs réponses possibles', 'Oui, pour les transports en commun |Oui, pour utiliser mon vélo ou le bike sharing|Oui, pour utiliser le car pooling ou le car sharing|Oui, pour utiliser la voiture|Non'],
			185 => ['Le parking interne est-il payant ?', '', 'Oui|Non'],
			186 => ['Quel est votre poste ?', 'Nous vous rappelons que le questionnaire s\'adresse indifféremment aux organismes publics, aux entreprises et aux écoles. Choisissez la classification la plus proche de vos fonctions effectives parmi les options ci-dessous', 'Ouvrier|Employé|Fonctionnaire|Cadre|Dirigeant(e)|Enseignant|Étudiant|Personnel ATA|Autre'],
			187 => ['Quel type de contrat avez-vous ?', '', 'Déterminé|Indéterminé|Consultant(e)|Autre'],
			188 => ['Quel type d\'horaire avez-vous ?', '', 'Journalier|Temps partiel vertical|Temps partiel horizontal|Crédit - Débit'],
			189 => ['Travaillez-vous par équipes ?', 'Selon le décret législatif n° 66 du 8 avril 2003 (« Mise en œuvre des directives 93/104/CE et 2000/34/CE concernant certains aspects de l\'aménagement du temps de travail »), on entend par : « travail posté » toute méthode d\'organisation du travail, y compris en équipes, selon laquelle des travailleurs sont successivement affectés aux mêmes postes de travail selon un rythme déterminé, y compris le rythme rotatif, qui peut être continu ou discontinu, et qui implique la nécessité pour les travailleurs d\'effectuer un travail à des heures différentes sur une période déterminée de jours ou de semaines.', 'Oui, en horaire fixe (je travaille toujours sur le même quart)|Oui, en horaire variable (j’alterne matin, après-midi, soir/nuit)|Non'],
			190 => ['Sur quel poste travaillez-vous cette semaine ?', 'Plusieurs réponses possibles', 'Premier quart (matin)|Deuxième quart (après-midi)|Troisième poste (soir/nuit)|Central (matin/après-midi)|En fonction des cours'],
			191 => ['Y a-t-il une flexibilité horaire à l\'entrée/sortie ?', '', 'Oui|Non'],
			192 => ['Votre entreprise prévoit-elle la possibilité de travailler depuis chez vous ?', '', 'Oui, en télétravail|Oui, en smart working|Non|Oui, les deux'],
			193 => ['Combien de jours par semaine en moyenne travaillez-vous depuis chez vous ?', '', '1 jour/semaine|2 jours/semaine|3 jours/semaine|4 jours/semaine|5 jours/semaine|6 jours/semaine|Jamais'],
			194 => ['Combien de jours par semaine effectuez-vous votre trajet ?', '', 'Un|Deux|Trois|Quatre|Cinq|Six'],
			195 => ['Combien de minutes dure en moyenne votre trajet aller, pauses comprises ?', '', 'Moins de 15 minutes|Entre 15 et 30 minutes|Entre 30 et 45 minutes|Entre 45 et 60 minutes|Entre 60 et 75 minutes|Entre 75 et 90 minutes|Plus de 90 minutes'],
			197 => ['Quelle ligne de transport en commun utilisez-vous pour votre trajet ?', 'ex. : 5, 5/, 13, 106CN, Ligne C', ''],
			198 => ['À quelle heure sortez-vous habituellement du travail le vendredi ?', '', 'entre 12:00 et 12:30|entre 12:30 et 13:00|entre 13:00 et 13:30|entre 13:30 et 14:00|entre 14:00 et 14:30|après 14:30|travail posté'],
			199 => ['Suivez-vous des cours en enseignement à distance ?', '', 'Oui|Non'],
			200 => ['Combien de jours par semaine suivez-vous des cours en enseignement à distance ?', '', '1 jour par semaine|2 jours par semaine|3 jours par semaine|4 jours par semaine|5 jours par semaine|6 jours par semaine|Aucun'],
			202 => ['Rentrez-vous chez vous pour le déjeuner ?', '', 'Oui|Non'],
			203 => ['Quelle distance parcourez-vous réellement pour vous rendre au travail ?', 'Calculez la distance en tenant compte de tous les déplacements que vous effectuez (pas seulement la distance directe domicile-travail)', 'jusqu\'à 1km;|jusqu\'à 3km|jusqu\'à 5km|de 5 à 15km; |de 16 à 20km|de 21 à 30km|de 31 à 50km|plus de 50 km'],
			204 => ['Combien de minutes dure en moyenne votre trajet retour, pauses comprises ?', '', 'Moins de 15 minutes|Entre 15 et 30 minutes|Entre 30 et 45 minutes|Entre 45 et 60 minutes|Entre 60 et 75 minutes|Entre 75 et 90 minutes|Plus de 90 minutes'],
			205 => ['Si vous utilisez une combinaison de moyens de transport pour le trajet aller-retour, indiquez-les tous', 'Plusieurs réponses possibles', 'À pied (pour un trajet >15 minutes)|Bus/tram|Métro GTT|Voiture|Moto/Scooter|Vélo|Trottinette|Taxi|Service ferroviaire Trenitalia/GTT|Service ferroviaire autres opérateurs (Trenord, Italo, Alta Velocità, ...)|Car sharing|Bike sharing|Moto en libre-service|Trottinette en libre-service|Navette d\'entreprise|Car pooling'],
			206 => ['Indiquez le code postal du lieu de départ de votre trajet', 'Cette donnée fait partie des informations minimales à collecter selon les lignes directrices ministérielles (Décret interministériel 179/2021)', ''],
			207 => ['Si vous pouviez choisir le type d\'incitation, laquelle préféreriez-vous ?', '', 'Échelonnement sur la fiche de paie du coût des titres de transport|Réduction sur le coût des titres de transport|Échelonnement sur la fiche de paie du coût d’un vélo (y compris à assistance électrique)|Réduction sur le coût d’achat d’un vélo|Réduction sur le coût d’achat d’une trottinette|Abonnement offert/réduit au service de trottinettes en libre-service|Abonnement offert/réduit au bikesharing|Convention stationnement-transport en commun (ex. Park&Ride, Velostazione)|Aucun des précédents'],
			208 => ['Seriez-vous disposé(e) à acheter un abonnement annuel si des incitations étaient proposées ?', '', 'Oui, en cas d’échelonnement sur la fiche de paie|Oui, en cas d’application d’une réduction sur le coût de l’abonnement|Oui, s’il y avait une convention parking-transports en commun (ex. park&ride, velostazione)|Non|Autre'],
			209 => ['Quelle est votre fonction ?', '', 'Agent de contrôle du stationnement|Assistant(e) à la clientèle|Personnel des Centres Opérationnels |Chef de poste, gradé|Personnel de conduite|Personnel opérationnel Ferroviaire et Métro'],
			212 => ['Quel est le lieu de votre travail ?', '', 'Direzione e CSC corso Turati|Comprensorio Nizza (Deposito e palazzina c.so Bramante)|Deposito Gerbido|Comprensorio San Paolo (Deposito, sedi corso Trapani e via Monginevro)|Deposito Venaria|Comprensorio Tortona-Manin e via Fontanesi|Sede Metro Collegno|Corso Francia 6|Autre'],
			213 => ['Écrivez dans quel bureau vous travaillez', '', ''],
			215 => ['Pour réduire le trafic et la surcharge des transports en commun, seriez-vous disposé(e) à', '', 'Prendre le service avant 8h00 |Prendre le service après 10h00|Non, ce n\'est pas possible pour moi'],
			218 => ['Quelle est la destination de votre trajet ?', 'Indiquez l\'adresse de votre LIEU DE TRAVAIL où vous vous rendez le matin (ou la plupart des jours de la semaine)', ''],
			221 => ['Comment vous rendez-vous le plus souvent au travail ?', 'Ce groupe de questions concerne le trajet que vous effectuez pour vous rendre au travail', 'À pied|Vélo|Moto/Motocyclette|Bus interurbain|Bus, tram ou Métro|Train|Voiture en tant que passager|Voiture en tant que conducteur|Carpooling (je m\'arrange avec les collègues)|Voiture + Train ou Bus/Tram/Métro|Tramway + vélo'],
			232 => ['Comment vous rendez-vous au travail en été ?', '', 'voiture|vélo|scooter|vélo électrique|à pied|train|bus'],
			237 => ['Combien de moyens de transport utilisez-vous pour aller au travail ?', '', '1|2|3|4|5|6'],
			238 => ['Au retour, utilisez-vous les mêmes moyens de transport qu\'à l\'aller ?', '', 'Oui|Non'],
			239 => ['Rencontrez-vous des embouteillages ou des files d\'attente sur votre trajet domicile-travail / travail-domicile ?', '', 'Tous les jours|Parfois|Uniquement à l’aller ou au retour|Jamais'],
			240 => ['Vous arrive-t-il souvent de devoir rester le soir ou de devoir sortir pour des raisons imprévues pendant la journée ?', '', 'Oui|Non'],
			241 => ['S\'il y avait un arrêt plus proche de votre lieu de travail et/ou de votre domicile, seriez-vous disposé(e) à utiliser les transports en commun ?', '', 'Oui|Non'],
			242 => ['L\'urgence Covid a-t-elle influencé votre choix de moyen de transport pour le trajet domicile-travail ?', '', 'Oui|Non'],
			245 => ['Lieu de travail', 'Comment travaillez-vous actuellement ?', 'Sur site|En télétravail|Aussi bien sur site qu’en smart working'],
			246 => ['Télétravail', 'Combien de jours par semaine en télétravail ?', '1 jour|2 jours|3 jours|4 jours|5 jours'],
			254 => ['Moyen de transport fréquemment utilisé', 'Quel moyen de transport utilisez-vous le plus fréquemment pour vous rendre au travail ?', 'À pied|Voiture en tant que conducteur|Vélo|Motocyclette|Bus|Train|Voiture en tant que passager'],
			283 => ['Combien de moyens de transport utilisez-vous pour aller au travail ?', '', 'À pied|Vélo|Moto/Motocyclette|Bus urbain/interurbain|Voiture en tant que passager|Voiture en tant que conducteur|Car Pooling|Voiture + Train ou Bus|Train + Vélo'],
			286 => ['En hiver, utilisez-vous les mêmes moyens de transport qu\'en été ?', '', 'Oui|Non'],
			287 => ['À quelle fréquence effectuez-vous des déplacements professionnels ?', '', 'Plusieurs fois par semaine|1 ou 2 fois par semaine|Moins d\'une fois par mois|Je n\'effectue jamais de déplacements professionnels|Occasionnellement'],
			290 => ['Recevez-vous une incitation pour les frais de votre trajet ?', '', 'Un|Deux|Trois|Quatre|Cinq|Six'],
			291 => ['Avez-vous la possibilité de travailler depuis chez vous ?', '', 'de 14:00 à 14:30|de 14:30 à 15:00|de 15:00 à 15:30|de 15.30 à 16:00|de 16:00 à 16.30|de 16.30 à 17:00|de 17:00 à 17:30|de 17:30 à 18:00|après 18:00|travail posté'],
			292 => ['Quelle serait votre propension à utiliser une trottinette électrique pour vous rendre au travail ?', '', 'Oui, pour les transports en commun|Oui, pour utiliser mon vélo ou le bike sharing |Oui, pour utiliser le car pooling ou le car sharing |Oui, pour utiliser la voiture |Non, mais cela pourrait m\'intéresser'],
			293 => ['À QUELLE DISTANCE SE TROUVE L\'ARRÊT DE TRANSPORT EN COMMUN LE PLUS PROCHE DU LIEU DE DÉPART DE VOTRE TRAJET ?', '', 'Ouvrier|Employé|Cadre|Dirigeant(e)|Stagiaire|Autre'],
			294 => ['Si vous arrivez au travail en voiture, vous avez tendance à :', '', 'Journalier|Temps partiel vertical |Temps partiel horizontal |Poste'],
			297 => ['Avez-vous déjà essayé de changer de mode de transport pour atteindre le lieu de travail sans voiture privée ? Si oui, décrivez les difficultés rencontrées.', '', 'Journalier|Temps partiel vertical|Temps partiel horizontal|Crédit - Débit'],
			298 => ['Y a-t-il une flexibilité horaire à l\'entrée/sortie ?', '', 'Oui|Non'],
			299 => ['INDIQUEZ TOUS LES MOYENS DE TRANSPORT UTILISÉS POUR LE TRAJET ALLER-RETOUR, Y COMPRIS CEUX UTILISÉS EN COMBINAISON (EX. VOITURE + BUS + TRAJET À PIED).', 'Télétravail : travail effectué à distance de son propre bureau, avec un lieu et des horaires strictement définis. Smart working : le salarié exerce son activité en dehors du bureau, mais décide en pleine autonomie des temps et du lieu de travail, sans poste fixe.', 'Oui, en télétravail|Oui, en smart working|Non'],
			301 => ['Quel est votre lieu de travail', '', 'Possible|Impossible |Absolument réalisable'],
			302 => ['Quelle est la destination de votre trajet ?', '', 'Microtecnica - Torino|Microtecnica - Luserna San Giovanni'],
			304 => ['Indiquez dans l\'espace ci-dessous toute autre remarque sur le thème de la mobilité', '', '<100 m|entre 100 et 500m|> 500m'],
			305 => ['SERVICE DE TRANSPORT COLLECTIF D\'ENTREPRISE', '', 'Se garer correctement près de l\'établissement|Se garer correctement loin de l\'établissement en effectuant un petit trajet à pied|Se garer près de l\'établissement même dans des zones non autorisées'],
			306 => ['S\'il y avait une navette qui s\'arrête à un point de rencontre, l\'utiliseriez-vous ?', '', ''],
			308 => ['Utilisez-vous une combinaison de moyens de transport pour le trajet aller-retour ? Indiquez-les tous.', 'Plusieurs réponses possibles. Si une combinaison de moyens de transport N\'EST PAS disponible, indiquez uniquement le seul moyen utilisé.', 'À pied (pour un trajet >15 minutes)|Bus/tram|Métro GTT|Voiture|Moto/Scooter|Vélo|Trottinette|Taxi|Service ferroviaire Trenitalia/GTT|Service ferroviaire autres opérateurs (Trenord, Italo, Alta Velocità, ...)|Car sharing|Bike sharing|Moto en libre-service|Trottinette en libre-service|Navette d\'entreprise|Car pooling'],
			309 => ['Votre trajet sur la carte', 'Indiquez l\'adresse de votre lieu de travail', 'Sede operativa Adriano Sada|Sede operativa Davide Negro|Sede operativa Carlo Ghiglieno|Sede operativa Ferdinando Prat|Sede operativa Pietro Cinotto'],
			310 => ['Émissions Voiture', '', ''],
			319 => ['Émissions Moto', 'Si l\'entreprise mettait à disposition un système de transport collectif d\'entreprise (navette/bus privé), Y ADHÉRERIEZ-VOUS ET À QUELLE CONDITION ?', 'Aucune, je ne suis de toute façon pas intéressé(e).|Uniquement si c’était gratuit|Même payant, pourvu que le coût soit inférieur au transport privé actuel|Uniquement si les horaires de départ et d’arrivée coïncident avec l’horaire actuel|Même si les horaires de départ et d\'arrivée impliquent une modification (décalage) par rapport à l\'horaire actuel|Uniquement si le temps de transport global reste similaire à l’actuel (max 25%) |Même si le temps de trajet global implique une augmentation significative (plus de 25%)|Même si cela nécessite de se rendre de manière autonome à des arrêts prédéfinis|Uniquement si je peux adhérer/payer pour des trajets/journées individuels|Même si cela nécessite un abonnement mensuel continu'],
			325 => ['Quelle est la destination de votre trajet ?', '', 'Sede principale - Piazza 4 novembre|Agrario - via Nino Manera, 13|IPC - Via Nino Manera, 33|Plesso Piazza D’Armi - SP 36|Plesso Baruffi - via E. Tortora|IIS Giolitti Paire - Piazza Stazione|Autre'],
			337 => ['Quel type de moyen de transport utilisez-vous pour aller au travail ?', '', 'Oui|Non'],
			339 => ['Combien de moyens de transport utilisez-vous pour aller au travail ?', '', 'Je n\'utilise pas de combinaison|Bus/Tram|Voiture|Moto/Scooter|Vélo|Trottinette|Taxi|Service ferroviaire Trenitalia/GTT|Service ferroviaire autres opérateurs (Trenord, Italo, Alta velocità...)|Car sharing (partage de voiture avec quelqu\'un)|Moto en libre-service (partage de moto avec quelqu\'un)|Navette d\'entreprise|À pied (pour un trajet >15 minutes)'],
			340 => ['Votre trajet sur la carte', '',''],
			341 => ['Au retour, utilisez-vous les mêmes moyens de transport qu\'à l\'aller ?', '', 'Euro 0|Euro 1|Euro 2|Euro 3|Euro 4|Euro 5|Euro 6'],
			342 => ['Choisissez le type de moyen de transport', '', 'Euro 0|Euro 1|Euro 2|Euro 3|Euro 4|Euro 5|Euro 6'],
			343 => ['Comment vous rendez-vous au travail ?', '', 'voiture|à pied|vélo|moto/motocycle|bus interurbain|bus, tramway et métro|train|voiture en tant que passager|voiture en tant que conducteur|carpooling (je m\'arrange avec mes collègues pour partager une voiture)'],
			344 => ['Comment vous rendez-vous à l\'école ?', '', '1|2|3|4|5'],
			345 => ['Au retour, utilisez-vous les mêmes moyens de transport qu\'à l\'aller ?', '', 'oui|non, je rentre avec les moyens de transport suivants.......'],
			346 => ['Êtes-vous disposé(e) à laisser le Mobility Manager intervenir en classe pour sensibiliser les élèves sur le sujet ?', '', 'bus urbain|bus interurbain|tramway|navette d\'entreprise'],
			354 => ['Êtes-vous disposé(e) à mener des activités liées à la mobilité durable ?', 'Pour vous rendre au travail, voyagez-vous seul(e) ou accompagné(e) ?', 'je viens seul, en voiture ou en moto|je viens seul, à vélo ou en trottinette|je viens seul, à pied|j\'utilise les transports en commun|je partage la voiture avec une autre personne|je partage la voiture avec deux personnes ou plus|parfois j\'arrive à partager la voiture mais la plupart du temps je voyage seul'],
			355 => ['S\'il y avait des pistes cyclables sur le trajet domicile-travail, les utiliseriez-vous ?', 'Décrivez le moyen de transport que vous utilisez pour vous rendre à l\'école et rentrer chez vous', 'en voiture ou en moto|à vélo ou en trottinette|cela dépend des conditions météorologiques|j\'utilise les transports en commun|aucune des réponses précédentes'],
			356 => ['Dans quels bureaux travaillez-vous ?', 'En tant qu\'enseignant(e), pensez-vous qu\'il est utile que les élèves comprennent ce qu\'est la mobilité durable et qu\'ils transmettent ces concepts à leurs familles ?', 'oui, le MM peut intervenir en classe pendant mes heures de cours, en les convenant|oui, je suis disposé à accorder une heure|le sujet doit être traité mais je préférerais pas pendant mes heures|non, je ne considère pas utile d\'utiliser des heures de cours pour traiter le sujet'],
			357 => ['La destination de votre trajet est-elle au centre pour l\'emploi de :', 'Pendant vos heures de cours, êtes-vous disposé(e) à mener des activités impliquant les élèves sur ce thème, de votre propre initiative ou suggérées par le Mobility Manager, y compris dans le cadre des heures prévues pour l\'éducation civique ?', 'oui, en suivant les suggestions du MM|oui, des activités sur le sujet font déjà partie de ma programmation d\'éd. civique|non, je n\'ai pas l\'intention de traiter le sujet'],
			358 => ['Quelle est la destination de votre trajet ?', 'Est-il possible de rejoindre votre école à vélo en toute sécurité ? Si oui, l\'utilisez-vous ? Si non, l\'utiliseriez-vous ?', 'il y a des pistes cyclables et je les utilise|il y a des pistes cyclables mais je ne les utilise pas|il y a des pistes cyclables mais seulement sur certains tronçons, et les routes sont très fréquentées, il n\'est pas prudent de venir au travail|il n\'y a pas de pistes cyclables, mais s\'il y en avait je les utiliserais certainement|il n\'y a pas de pistes cyclables, mais s\'il y en avait je les utiliserais occasionnellement|il n\'y a pas de pistes cyclables, mais même s\'il y en avait je ne les utiliserais pas de toute façon'],
			366 => ['Êtes-vous un employé interne ou externe ?', '', ''],
			368 => ['La destination de votre trajet est-elle au centre pour l\'emploi de :', '', 'Torino Sud|Torino nord|Moncalieri|Ciriè|Pinerolo|Rivoli|Ivrea|Cuorgnè|Orbassano|Susa|Venaria Reale|Chivasso|Settimo Torinese|Carmagnola|Cuneo|Alba|Bra|Fossano|Savigliano|Mondovì|Saluzzo|Ceva|Acqui Terme|Alessandria|Casale Monferrato|Novi Ligure|Tortona|Asti|Canelli|Nizza Monferrato|Ovada|Villanova D\'Asti|Biella|Novara|Borgomanero|Domodossola|Verbania|Vercelli|Borgosesia|Chieri|Omegna|Torino via Avogadro'],
