			377 => ['Quel moyen de transport utilisez-vous principalement pour les déplacements en ville pendant les heures de travail ?', '', 'Voiture privée|Voiture de service|Transports en commun|Car sharing|Vélo|Trottinette'],
			378 => ['Pour les déplacements professionnels en ville, quel moyen de transport préféreriez-vous si possible ?', '', 'Voiture privée|Voiture de service|Transports en commun|Car sharing|Vélo|Trottinette|Marche à pied'],
			380 => ['Quelle est la destination de votre trajet ?', 'Indiquez le lieu de travail auquel vous êtes affecté(e)', 'Via Alfieri, 15 |P.zza Solferino, 22 |Via Arsenale, 14|Via Arsenale, 12|Via San Francesco D\'Assisi, 35'],
			428 => ['À QUELLE DISTANCE SE TROUVE L\'ARRÊT DE TRANSPORT EN COMMUN LE PLUS PROCHE DU LIEU DE DÉPART DE VOTRE TRAJET ?', '', '< 100 mt|> 100 mt'],
			429 => ['SI VOUS POUVIEZ CHOISIR LE TYPE D\'INCITATION, LAQUELLE PRÉFÉRERIEZ-VOUS ?', '', 'Incitation à l\'achat d\'un abonnement de transport en commun (Réduction/prélèvement sur salaire, etc.)|Abonnement offert/réduit au car sharing|Abonnement offert/réduit au bike sharing/trottinettes|Bon annuel pour entretien/révision vélo|Convention de stationnement (ex. Park&Ride, Velostazione)|Disponibilité de parking interne pour car pooling (< 3 / voiture)|Autre'],
			439 => ['UTILISEZ-VOUS UNE COMBINAISON DE MOYENS DE TRANSPORT POUR LE TRAJET ALLER-RETOUR ? SI OUI INDIQUEZ-LES TOUS, SI NON INDIQUEZ LE MOYEN UNIQUE', '', 'À pied (pour un trajet >15 minutes)|Bus/tram|Métro GTT|Voiture|Moto/Scooter|Vélo|Trottinette|Taxi|Service ferroviaire Trenitalia/GTT|Service ferroviaire autres opérateurs (Trenord, Italo, Alta Velocità, ...)|Car sharing|Bike sharing|Moto en libre-service|Trottinette en libre-service|Navette d\'entreprise|Car pooling'],
			440 => ['QUELLE EST LA DESTINATION DE VOTRE TRAJET ?', '', 'Arca Technologies S.r.l. Via Statale 17 Bollengo TO'],
			443 => ['SI VOUS UTILISEZ UNE COMBINAISON DE MOYENS DE TRANSPORT POUR LE TRAJET ALLER-RETOUR, INDIQUEZ-LES TOUS', '', 'À pied (pour un trajet >15 minutes)|Bus/tram|Métro GTT|Voiture|Moto/Scooter|Vélo|Trottinette|Taxi|Service ferroviaire Trenitalia/GTT|Service ferroviaire autres opérateurs (Trenord, Italo, Alta Velocità, ...)|Car sharing|Bike sharing|Moto en libre-service|Trottinette en libre-service|Navette d\'entreprise|Car pooling|J\'utilise un seul moyen de transport'],
			453 => ['Quelle est la destination de votre trajet ?', '', 'Sede ex Don Bosco|Presidio Territoriale Nizza|Ospedale Cardinal Massaia'],
			454 => ['Le moyen de transport que vous utilisez pour le trajet domicile-travail est-il fourni par votre employeur ?', '', 'Incitation à l\'achat d\'un abonnement de transport en commun (Réduction/prélèvement sur salaire, etc.)|Abonnement offert/réduit au car sharing|Abonnement offert/réduit au bike sharing/trottinettes|Bon annuel pour entretien/révision vélo|Convention de stationnement (ex. Park&Ride, Velostazione)|Disponibilité de parking interne pour car pooling (< 3 / voiture)|Autre'],
