			482 => ['Combien de jours par mois utilisez-vous le service de navette d\'entreprise ?', '', 'Jamais|Moins de 5|Entre 5 et 10|Entre 10 et 15|Plus de 15'],
			483 => ['Pour quelles raisons n\'utilisez-vous pas plus souvent la navette d\'entreprise ?', '', 'Arrêts trop éloignés de mon domicile|Horaires peu pratiques|Temps de trajet excessif|Coût trop élevé|Je préfère d’autres moyens de transport|J\'ai besoin de la voiture pour d\'autres besoins|Autre'],
			484 => ['Seriez-vous intéressé(e) par un abonnement aux transports en commun à prix réduit et une navette reliant le bureau aux arrêts de train/bus les plus proches ?', '', 'Oui|Oui, beaucoup|Oui, assez intéressé|Non'],
			486 => ['Dans quel bureau travaillez-vous principalement ?', '', 'Torino'],
			487 => ['Pensez-vous que l\'entreprise fait quelque chose pour encourager la mobilité durable ?', '', 'Oui|Non|Pas suffisamment'],
			488 => ['Que voudriez-vous que l\'entreprise fasse davantage ?', '', 'Événements|Des incitations plus conséquentes|Meilleure communication|Workshop|Autre'],
			489 => ['Pensez-vous que les réductions offertes par l\'entreprise sont suffisantes ?', '', 'Oui |Non'],
