			493 => ['Combien utiliseriez-vous une navette vous reliant aux arrêts de transport en commun les plus proches (ex. Volpiano-Settimo Torinese (FS, GTT, etc.) ?', '', 'Tous les jours|Au moins quelques jours par semaine|Au moins quelques jours par mois|Jamais'],
			494 => ['Si l\'entreprise permettait à ses employés de recharger gratuitement leur voiture électrique, envisageriez-vous un remplacement de votre voiture dans les 18 prochains mois ?', '', 'Oui|Non|Je possède déjà une voiture rechargeable'],
			496 => ['QUEL EST VOTRE POSTE ?', '', 'Enseignant(e)|Chercheur/chercheuse|Technologue|Technicien/ne|Administratif/ve|Boursier/ère'],
			497 => ['Choisissez le type de voiture', '', 'Taxi|Personnel|Car pooling|Car sharing'],
			498 => ['Choisissez si vous êtes conducteur ou passager', '', 'Personnel en tant que conducteur|Personnel en tant que passager'],
			499 => ['Choisissez le type de vélo', '', 'Personnel|Bike sharing'],
			500 => ['Choisissez le type de moto', '', 'Personnel|Moto ou scooter en libre-service'],
			501 => ['Choisissez le type de train', '', 'Service ferroviaire Trenitalia|Service ferroviaire autres opérateurs (Trenord, Italo, Alta Velocità...)'],
			502 => ['Global - Choisissez le type de trottinette', '', 'Personnel|Scooter sharing'],
			505 => ['À quelle catégorie appartenez-vous ?', 'Choisissez une seule des réponses suivantes :', 'Étudiant|Enseignant|Parent|Personnel A.T.A'],
			506 => ['À quel niveau d\'enseignement travaillez-vous ?', '', 'École maternelle|École primaire (élémentaire)|École secondaire de premier cycle (collège)|École secondaire de second cycle (lycée)'],
			507 => ['L\'école où j\'enseigne se trouve dans une zone :', '', 'Avec peu de trafic|Avec beaucoup de trafic'],
			508 => ['L\'école où j\'enseigne se trouve dans une zone avec beaucoup de trafic :', '', 'Toute la journée|Uniquement aux horaires d’entrée/sortie de l’école'],
			509 => ['Autour de l\'école, la signalisation :', '', 'Elle n\'est généralement pas respectée, avec des comportements dangereux|Elle est généralement respectée'],
			510 => ['La plupart des usagers et du personnel scolaire rejoignent l\'établissement :', 'Choisissez une seule des réponses suivantes :', 'À pied/à vélo/en transport en commun|En voiture'],
			511 => ['Avez-vous participé à des parcours d\'éducation à la mobilité durable et/ou à la sécurité routière ?', '', 'Oui|Non'],
			512 => ['Vos habitudes de déplacement domicile-école ont-elles changé après avoir participé aux parcours d\'éducation à la mobilité durable et/ou à la sécurité routière ?', '', 'Oui, j’ai changé mes habitudes et maintenant je me rends à l’école à pied/à vélo ou en transport en commun|Oui, je viens en voiture, mais je parcours au moins les 200 derniers mètres à pied ou à vélo|Non, car j\'allais déjà à l\'école à pied/en vélo ou en transport en commun|Non, mes habitudes de déplacement n\'ont pas changé|Je ne saurais pas'],
			513 => ['Quels parcours éducatifs (sur le thème de la sécurité routière et de la mobilité durable) ont été proposés ?', 'Écrivez votre réponse ici :', 'Oui|Non'],
			514 => ['L\'école s\'est-elle dotée d\'un Plan de Déplacements Domicile-École ?', 'Choisissez une seule des réponses suivantes :', 'Oui|Non|Je ne sais pas'],
			515 => ['Un Mobility Manager scolaire a-t-il été désigné (également en collaboration entre plusieurs établissements/Directions éducatives) ?', 'Choisissez une seule des réponses suivantes :', 'Oui|Non|Je ne sais pas'],
			516 => ['Le Conseil d\'établissement / le Collège des enseignants a-t-il approuvé la création d\'une Commission visant à impliquer les enseignants et les parents dans les questions de mobilité durable ?', '', 'Oui|Non'],
			517 => ['Le POF (Plan de l\'Offre Éducative) prévoit-il des activités liées à la mobilité durable ?', '', 'Oui|Non'],
			518 => ['Quel niveau d\'enseignement fréquentez-vous ?', '', 'École maternelle|École primaire (élémentaire)|École secondaire de premier cycle (collège)|École secondaire de second cycle (lycée)'],
			519 => ['En quelle classe êtes-vous ?', '', 'Première|Deuxième|Troisième|Quatrième|Cinquième'],
			520 => ['Combien de minutes dure en moyenne le trajet domicile-école, pauses comprises ?', '', 'Première|Deuxième|Troisième'],
			521 => ['À quelle heure arrivez-vous à l\'école ?', 'Choisissez une seule des réponses suivantes :', 'Première|Deuxième|Troisième|Quatrième|Cinquième'],
			522 => ['Qui vous accompagne habituellement à l\'école ?', 'Choisissez une seule des réponses suivantes :', 'Moins de 15 minutes|Entre 15 et 30 minutes|Entre 30 minutes et une heure|Plus d’une heure'],
			523 => ['Habituellement, qui accompagne votre enfant à l\'école ?', 'Pour les parents : à quelle heure votre enfant arrive-t-il à l\'école ?', 'Avant 7h40|Entre 7.41 et 7.50|Entre 7.51 et 8.00|Entre 8.01 et 8.10|Entre 8.11 et 8.20|Entre 8.21 et 8.30|Entre 8.31 et 8.40'],
			524 => ['Avec quel moyen de transport aimeriez-vous vous rendre à l\'école ?', 'Choisissez une seule des réponses suivantes :', 'Papa/maman|Grands-parents/oncles-tantes|Avec mon frère / avec ma sœur|Avec des amis / avec des amies|J\'y vais seul/e|Autre'],
			525 => ['Pourquoi ?', 'Choisissez une seule des réponses suivantes :', 'Un parent|Grands-parents ou oncles/tantes|Un frère / une sœur|Va avec des ami(e)s|Va à l\'école seul/e|Autre'],
			526 => ['Afin de comprendre la sécurité aux abords de l\'école, lorsque vous arrivez ou repartez de l\'école, vous arrêtez-vous pour attendre ou parler avec des amis près de l\'école ?', '', 'À pied|À vélo|En train|En bus|En voiture|En cyclomoteur/motocyclette|Avec plusieurs moyens de transport|Autre'],
			527 => ['L\'espace où vous vous arrêtez est-il sûr et protégé du trafic ?', '', 'C\'est plus amusant|C\'est plus confortable|C\'est moins dangereux|Je mets moins de temps|Je suis plus autonome|Autre'],
			528 => ['Que faudrait-il pour permettre aux élèves de se rendre à l\'école à pied en toute sécurité ?', '', 'Oui|Non'],
			529 => ['Que faudrait-il pour permettre aux élèves de se rendre à l\'école à vélo en toute sécurité ?', '', 'Oui|Non'],
			530 => ['Qu\'est-ce qui vous dérange le plus parmi les éléments suivants ?', '', 'Oui|Non'],
			531 => ['Comment résoudriez-vous le problème du trafic et de la pollution ?', '', 'Oui, j’ai changé mes habitudes et maintenant je me rends à l’école à pied/à vélo ou en transport en commun|Oui, je viens en voiture, mais je parcours au moins les 200 derniers mètres à pied ou à vélo|Non, car j\'allais déjà à l\'école à pied/en vélo ou en transport en commun|Non, mes habitudes de déplacement n\'ont pas changé|Je ne saurais pas'],
			532 => ['Selon vous, dans les rues autour de l\'école, MARCHER', 'Plusieurs réponses possibles', 'Plus de chemins piétons protégés (par ex. avec des barrières empêchant les voitures d’occuper les espaces piétons, avec des carrefours surélevés pour garantir que les voitures ralentissent aux endroits où les élèves traversent la rue)|Plus d’interventions pour ralentir les véhicules|Présence d’adultes aidant les élèves à traverser aux points les plus à risque|Autre'],
			533 => ['Pourquoi ?', 'Plusieurs réponses possibles', 'Plus de pistes cyclables protégées des voies réservées aux voitures|Plus d’interventions pour ralentir les véhicules|Présence d’adultes aidant les élèves à traverser aux points les plus à risque|Présence, à l’école, de parkings à vélos pratiques, sécurisés et couverts|Autre'],
			534 => ['Dans les rues autour de l\'école, prendre le BUS SCOLAIRE ou le BUS :', 'Plusieurs réponses possibles', 'Trafic et files d\'attente|Risque d’accidents et manque de sécurité routière|Pollution atmosphérique et sonore|Parcours ennuyeux et sans attraits|Difficulté à aller à pied ou à vélo (voitures trop rapides ou garées sur le trottoir)|Autre'],
			535 => ['Pour quelle raison allez-vous en voiture ?', 'Plusieurs réponses possibles', 'Plus de transports en commun|Billets de transport en commun moins chers|Plus de parcours réservés exclusivement aux transports en commun|Plus de zones interdites aux voitures|Plus de pistes cyclables|Autre'],
			536 => ['Dans les rues autour de l\'école, SE DÉPLACER À VÉLO :', '', 'C\'est sûr|C\'est dangereux'],
			537 => ['Comment ça ?', 'Plusieurs réponses possibles', 'Parce que les chemins piétons (trottoirs ou espaces réservés aux piétons) n’existent pas ou sont étroits ou sans protections|Parce que sur les chemins piétons il y a des éléments qui rendent le passage risqué (nids-de-poule, racines saillantes ou autres)|Parce que sur les chemins piétons il y a des éléments qui gênent le passage (poteaux, bennes ou autres)|Parce que la vitesse des véhicules met tout le monde en danger (piétons, cyclistes, autres automobilistes)|Parce qu’aux passages piétons les véhicules ne respectent pas les règles (ils ne s’arrêtent ni ne ralentissent)|Parce que les rues sont mal éclairées|Parce que le long des rues il y a peu de commerces ou d’autres points de repère (bibliothèque, centre de jeunesse, patronage, etc.)'],
			538 => ['Comment ça ?', '', 'Parce qu’il n’y a pas de pistes cyclables|Parce que les pistes cyclables ne sont pas séparées des voies de circulation|Parce qu’il y a des nids-de-poule ou des regards sur la chaussée|Parce qu’il y a des bennes ou d’autres éléments qui gênent le passage sur la chaussée|Parce que la vitesse des véhicules met tout le monde en danger (piétons, cyclistes, autres automobilistes)|Parce qu’aux carrefours les véhicules ne respectent pas les règles (ils ne s’arrêtent ni ne ralentissent)|Parce que les rues sont mal éclairées'],
			539 => ['Seriez-vous disposé(e) à utiliser un moyen de transport plus respectueux de l\'environnement ?', '', 'C\'est sûr|C\'est dangereux|Il n\'y a pas de bus/bus scolaires'],
			540 => ['Seriez-vous disposé(e) (ou la personne qui vous accompagne) à laisser le véhicule à 300 mètres de l\'entrée de l\'école et parcourir le dernier tronçon à pied ?', '', 'Parce que l’arrêt ne dispose pas d’un espace pour attendre en sécurité|Parce que l’arrêt n’est pas bien visible/signalé|Parce que l’arrêt ne dispose pas d’un passage piéton sécurisé à proximité|Parce que la vitesse des véhicules met tout le monde en danger (piétons, cyclistes, autres automobilistes)|Parce que le tronçon de route est mal éclairé'],
			541 => ['Seriez-vous disposé(e) à former un « covoiturage » en offrant ou acceptant un trajet dans la voiture d\'un collègue/camarade, avec un léger détour par rapport au parcours actuel ?', 'Plusieurs réponses possibles', 'Par habitude et commodité|Par nécessité|Pour des problèmes de santé|Pour des problèmes de sécurité'],
			542 => ['Résidez-vous dans la même province que le bureau où vous êtes affecté(e) ?', '', 'C\'est sûr|C\'est dangereux'],
			543 => ['Votre mode de travail prévoit-il le travail agile ?', 'Plusieurs réponses possibles', 'cela prend moins de temps et je peux me lever plus tard|mes parents passent par l\'école en allant au travail / en tant que parent allant au travail je passe déjà près de l\'école|la voiture me sert / sert à celui qui m\'accompagne pour d\'autres activités (courses, salle de sport…)'],
			544 => ['Quels jours vous rendez-vous habituellement au bureau ?', 'Plusieurs réponses possibles', 'Il n\'y a pas d\'arrêt de transport en commun à 5 minutes à pied du domicile/de l\'école ou le transport en commun passe trop tôt/tard|En arrivant à l\'école à pied/à vélo ou en transport en commun, je serais en retard (à l\'école / au travail)'],
			545 => ['Dans quelle mesure le temps passé dans les trajets domicile-travail et travail-domicile impacte-t-il votre vie privée (loisirs, sport, détente) ?', 'Plusieurs réponses possibles', 'Parce que les chemins piétons (trottoirs ou espaces réservés aux piétons) / les pistes cyclables n’existent pas|Parce que les pistes cyclables ne sont pas séparées des voies de circulation|Parce qu’il y a des nids-de-poule ou des regards sur la chaussée|Parce qu’il y a des bennes ou d’autres éléments qui gênent le passage sur la chaussée|Parce que la vitesse des véhicules met tout le monde en danger (piétons, cyclistes, autres automobilistes)|Parce qu’aux passages piétons les véhicules ne respectent pas les règles (ils ne s’arrêtent ni ne ralentissent)|Parce que les rues sont mal éclairées|Parce que le long des rues il y a peu de commerces ou d’autres points de repère (bibliothèque, centre de jeunesse, patronage, etc.)'],
			546 => ['Votre mode de déplacement habituel est-il source de stress pour vous ?', '', 'Oui|Uniquement si je mettais au maximum 10 minutes de plus|Uniquement si le trajet était sûr pour les piétons / les cyclistes|Non'],
			547 => ['Si votre contrat prévoit le télétravail, à combien s\'élèvent vos économies mensuelles ?', 'Choisissez une seule des réponses suivantes :', 'Oui, toujours|Oui, à la belle saison|Je ne sais pas|Non'],
			548 => ['Voyager ensemble : si vous utilisez la voiture privée pour les trajets domicile-travail et travail-domicile, seriez-vous disposé(e) à partager le trajet avec d\'autres collègues en divisant les frais ?', '', 'Je le fais déjà|Non|Oui|Oui, en partageant les frais|Uniquement si des formes de facilitation étaient prévues'],
			549 => ['Voyager ensemble : lorsque vous devez vous déplacer pour le travail vers d\'autres sites du Groupe Deda, vous renseignez-vous si d\'autres collègues doivent parcourir la même distance pour partager le trajet ?', '', 'Oui|Non'],
			550 => ['La voiture que vous utilisez pour vos trajets domicile-travail :', '', 'Oui, 1 jour par semaine|Oui, 2 jours par semaine|Oui, 3 jours par semaine|Oui, 4 jours par semaine|Oui, 5 jours par semaine|Oui, avec une flexibilité jusqu’à 75% du mois|Non'],
			551 => ['Quelle est la propension à utiliser une trottinette électrique pour se rendre au travail ?', '', 'Lundi|Mardi|Mercredi|Jeudi|Vendredi|Samedi|Dimanche'],
			552 => ['La voiture que vous utilisez pour vos trajets est-elle la vôtre ou une voiture de service ?', '', 'Beaucoup, il me reste peu de temps libre avant et après le travail|Pas beaucoup, car je passe peu de temps dans les déplacements|Cela n\'a pas d\'impact car je travaille toujours (ou très souvent) depuis chez moi'],
			553 => ['test', '', 'Oui, beaucoup|Non, le déplacement n\'affecte pas mon niveau de stress|Oui, mais la possibilité de faire quelques jours de smart working a réduit mon niveau de stress|Non car je n\'ai pas besoin de me déplacer de chez moi pour travailler'],
			554 => ['Sexe', '', '> 15%|15% - 30%|30% - 60%|60% - 100%|Mon contrat ne prévoit pas le télétravail'],
			555 => ['Tranche d\'âge', '', 'Non, je préfère voyager seul(e)|Oui, je le fais déjà|Je n\'utilise pas la voiture particulière|Je le ferais s\'il existait une application d\'entreprise pour se coordonner avec les collègues'],
			556 => ['Quel est votre poste ?', '', 'Non, je préfère voyager seul(e)|Je le ferais volontiers s\'il existait une application d\'entreprise pour se coordonner avec les collègues|Oui, je le fais souvent mais uniquement avec mes collègues de service|Je n\'effectue jamais de déplacements professionnels'],
			557 => ['Type d\'horaire', '', 'c\'est ma propriété/celle de mon ménage|c\'est la voiture de l\'entreprise|je n\'utilise pas la voiture pour mes déplacements domicile-travail'],
			558 => ['À quelle fréquence avez-vous habituellement recours au télétravail ?', 'Utiliseriez-vous des alternatives de mobilité par rapport à celles que vous utilisez habituellement ?', 'Possible|Impossible |Absolument réalisable'],
			559 => ['Êtes-vous employé(e) de l\'entreprise pour laquelle vous remplissez le questionnaire ?', '', 'Propre|Entreprise'],
			560 => ['Pourquoi choisissez-vous la voiture ?', 'sdasd', 'as|as'],
			561 => ['Pourquoi choisissez-vous la moto ?', '', 'Homme|Femme|Je préfère ne pas préciser'],
			562 => ['Où vous garez-vous habituellement ?', '', 'Moins de 30|30 - 39|40 - 49|50 - 59|60 ou plus'],
			563 => ['Combien de temps mettez-vous pour trouver une place de stationnement et rejoindre le lieu de travail ?', 'Choisissez la classification la plus proche de vos fonctions effectives parmi les options ci-dessous', 'Dirigeant(e)|Cadre|Employé|Ouvrier|Enseignant(e)|Étudiant|Autre'],
			564 => ['Habituellement, à quelle fréquence vous rendez-vous au travail au bureau indiqué ?', '', 'Horaire fixe et/ou avec flexibilité horaire|Horaire en rotation fixe|Horaire en rotation variable'],
			565 => ['À quelle heure arrivez-vous habituellement au travail ?', '', 'Jamais ou occasionnellement, pas plus de 2 ou 3 fois par mois|Fréquemment, quelques jours par semaine|Toujours, tous les jours de ma semaine de travail|À certaines périodes de l\'année'],
			566 => ['Habituellement, faites-vous des arrêts intermédiaires en allant au travail (ex. gestion des enfants, courses, rendez-vous, etc.) ?', '', 'Oui|Non, je travaille pour le compte d\'une autre société (ex. coopérative/agence d\'intérim/sous-traitant/fournisseur externe/autre)'],
			567 => ['Combien de temps mettez-vous habituellement pour vous rendre au travail au bureau indiqué ?', '', 'Par habitude (je n\'ai jamais envisagé ou essayé d\'alternatives)|En raison de ma mobilité physique ou sensorielle réduite|Pour la facilité de stationnement|Pour des raisons de temps et/ou de fiabilité|Parce que j’en ai besoin pour exercer mon activité professionnelle|Pour des besoins de conciliation vie professionnelle-vie privée (ex. accompagnement de proches, déplacements pendant la pause déjeuner, etc.)|Pour le confort de voyage (ex. je voyage seul(e) et assis(e), je ne suis pas dérangé(e) par d\'autres, je transporte des objets, frais en été et chaud en hiver, à l\'abri de la pluie, aucun trajet à pied, etc.)|Autre motivation'],
			568 => ['Habituellement, pendant la pause déjeuner :', '', 'Par habitude (je n\'ai jamais envisagé ou essayé d\'alternatives)|En raison de ma mobilité physique ou sensorielle réduite|Pour des raisons de temps et/ou de fiabilité|Pour des besoins de conciliation vie professionnelle-vie privée (ex. accompagnement de proches, déplacements pendant la pause déjeuner, etc.)|Pour le confort de voyage (ex. je voyage assis(e), je transporte des objets, frais en été et chaud en hiver, à l\'abri de la pluie, aucun trajet à pied, etc.)|Autre motivation'],
			569 => ['Quel moyen de transport utilisez-vous principalement pendant la pause déjeuner ?', '', 'Par habitude (je n\'ai jamais envisagé ou essayé d\'alternatives)|Pour la facilité de stationnement|Pour des raisons de temps et/ou de fiabilité|Parce que j’en ai besoin pour exercer mon activité professionnelle|Pour des besoins de conciliation vie professionnelle-vie privée (ex. accompagnement de proches, déplacements pendant la pause déjeuner, etc.)|Pour le confort de voyage (ex. je voyage seul(e) et assis(e), je ne suis pas dérangé(e) par d\'autres, aucun trajet à pied, etc.)|Autre motivation'],
			570 => ['À quelle heure sortez-vous habituellement du travail ?', '', 'Parking gratuit appartenant à l\'entreprise|Parking payant appartenant à l\'entreprise|Parking réservé qui m\'a été attribué par l\'entreprise|Parking public payant à proximité du site|Parking public gratuit à proximité du site|Autre solution de stationnement'],
			571 => ['Habituellement, faites-vous des arrêts intermédiaires en rentrant du travail (ex. gestion des enfants, courses, rendez-vous, etc.) ?', '', 'Moins d\'1 minute|1 - 5 minutes|6 - 10 minutes|Plus de 10 minutes'],
			572 => ['Êtes-vous satisfait(e) de vos habitudes de déplacement actuelles ?', '', '6 jours / semaine|5 jours / semaine|4 jours / semaine|3 jours / semaine|2 jours / semaine|1 jour / semaine'],
			573 => ['En été et en hiver, utilisez-vous les mêmes moyens de transport pour vous rendre au travail ?', '', 'Variable selon le poste hebdomadaire|avant 6:30|entre 6:30 et 6:45|entre 6:45 et 7:00|entre 7:00 et 7:15|entre 7:15 et 7:30|entre 7:30 et 7:45|entre 7:45 et 8:00|entre 8:00 et 8:15|entre 8:15 et 8:30|entre 8:30 et 8:45|entre 8:45 et 9:00|après 9:00'],
			574 => ['Quand il pleut ou qu\'il fait froid, comment vous déplacez-vous habituellement ?', '', 'Non, le trajet est direct|Oui, 1 - 3 fois par semaine|Oui, tous les jours'],
			575 => ['Pourquoi choisissez-vous ce mode de déplacement ?', 'En cas de trajet non direct, considérez également les étapes intermédiaires', 'Moins de 5 min|5 - 10 min|11 - 15 min|16 - 20 min|21 - 30 min|31 - 40 min|41 - 50 min|51 - 60 min|Plus d\'1 heure'],
			576 => ['Quand il fait beau ou chaud, comment vous déplacez-vous habituellement ?', '', 'Je reste sur site (ex. cantine d’entreprise)|Déjeuner hors site|Je rentre à la maison|Je ne prends pas de pause déjeuner'],
			577 => ['Pourquoi choisissez-vous ces modes de déplacement ?', '', 'À pied (> 5min)|Vélo musculaire / électrique, cargo-bike ou trottinette|Transport en commun (bus, métro, tramway, train)|Partage du véhicule avec les collègues (car pooling)|Véhicule automobile ou motocyclette'],
			578 => ['Seriez-vous disposé(e) à renoncer à la voiture ou à la moto pour le trajet domicile-travail au moins 3 jours par semaine ?', '', 'Variable selon le poste hebdomadaire|avant 14:00|entre 14:00 et 14:30|entre 14:30 et 15:00|entre 15:00 et 15:30|entre 15:30 et 16:00|entre 16:00 et 16:30|entre 16:30 et 17:00|entre 17:00 et 17:30|entre 17:30 et 18:00|entre 18:00 et 18:30|entre 18:30 et 19:00|après 19:00'],
			579 => ['À quelles conditions seriez-vous disposé(e) à utiliser les transports en commun (TC) pour votre trajet domicile-travail au moins 3 jours par semaine ?', '', 'Non, le trajet est direct|Oui, 1 - 3 fois par semaine|Oui, tous les jours'],
			580 => ['Connaissez-vous bien l\'offre de transport en commun urbain ?', 'Exprimez un avis en vous référant à la complexité de votre trajet domicile-travail.
1 = pas du tout satisfait(e), 5 = tout à fait satisfait(e)', '1|2|3|4|5'],
			581 => ['À quelles conditions seriez-vous disposé(e) à partager votre trajet en voiture avec des collègues (covoiturage) pour votre trajet domicile-travail au moins 3 jours par semaine ?', '', 'Oui|Non'],
			582 => ['À quelles conditions seriez-vous disposé(e) à utiliser le vélo pour votre trajet domicile-travail au moins 3 jours par semaine ?', '', 'À pied (> 5min)|Vélo musculaire / électrique ou trottinette|Navette d\'entreprise|Transport en commun (bus, métro, train)|Partage de la voiture avec les collègues (car pooling)|Voiture ou motocyclette'],
			583 => ['À quelles conditions seriez-vous intéressé(e) par un service de navette d\'entreprise ?', '', 'Par choix ou organisation de l’entreprise|Par habitude (je n\'ai jamais envisagé ou essayé d\'alternatives)|Transport de matériaux ou d\'outils de travail|Parce que c’est le moyen de transport le plus rapide|Parce que c’est le seul moyen pour atteindre la destination|Pour le confort de voyage (ex. je ne suis pas dérangé(e) par d\'autres, frais en été et chaud en hiver, à l\'abri de la pluie, aucun trajet à pied, etc.)'],
			584 => ['À quelles initiatives seriez-vous intéressé(e) ?', '', 'À pied (> 5min)|Vélo musculaire / électrique ou trottinette|Navette d\'entreprise|Transport en commun (bus, métro, train)|Partage de la voiture avec les collègues (car pooling)|Voiture ou motocyclette'],
			585 => ['Indiquez les initiatives de Mobility Management qui vous intéressent', '', 'Par habitude (je n\'ai jamais envisagé ou essayé d\'alternatives)|En raison de ma mobilité physique ou sensorielle réduite|Pour la facilité de stationnement|Pour des raisons de temps et/ou de fiabilité|Parce que j’en ai besoin pour exercer mon activité professionnelle|Pour des besoins de conciliation vie professionnelle-vie privée (ex. accompagnement de proches, déplacements pendant la pause déjeuner, etc.)|Pour le confort de voyage (ex. je voyage seul(e) et assis(e), je ne suis pas dérangé(e) par d\'autres, je transporte des objets, frais en été et chaud en hiver, à l\'abri de la pluie, aucun trajet à pied, etc.)|Autre motivation'],
			586 => ['Quelles sont les difficultés que vous rencontrez lors de votre trajet habituel domicile-travail ?', '', 'Je n\'utilise pas habituellement la voiture ou la moto|Non, je ne suis pas disponible|Oui, sous certaines conditions'],
			587 => ['Avez-vous des idées ou des suggestions ?', '', 'Arrêt de bus le plus proche des entrées du lieu de travail|Arrêt de bus le plus proche de mon domicile|Services plus fréquents|Fréquences accrues aux heures du soir et de la nuit|Plus de flexibilité horaire afin de pouvoir accéder aux services (ex. train, service interurbain, etc.)|Attribution de récompenses ou de reconnaissances économiques|Utilisation gratuite ou à tarif réduit des services|Aucune condition, je ne suis pas disposé(e) à utiliser les transports en commun'],
			588 => ['Quel moyen de transport utilisez-vous principalement lors des déplacements professionnels ?', '', 'Je connais bien et sais utiliser en toute autonomie le réseau de transport et les outils d\'accès (ex. RERpp!)|Je ne connais que la ligne de métro et la ligne de bus à proximité de mon domicile|Je ne le connais pas, mais j\'aimerais en savoir plus'],
			589 => ['Pourquoi choisissez-vous ce mode pour les déplacements professionnels ?', '', 'Connaissance et confiance avec les compagnons de voyage potentiels|Plus de flexibilité horaire permettant la conciliation des horaires entre collègues|Disponibilité d\'une plateforme numérique pour l\'échange de trajets|Disponibilité de voitures de service pour le car pooling|Présence, dans l’entreprise, de places de stationnement réservées au car pooling|Attribution de récompenses et/ou d\'incitations économiques pour les covoitureurs|Aucune condition, je ne suis pas disposé(e) au covoiturage'],
			590 => ['Où vous rendez-vous le plus fréquemment pour des raisons professionnelles ?', '', 'Amélioration des conditions de sécurité sur le trajet que je dois parcourir|Disponibilité d\'un service gratuit d\'entreprise de vélos électriques en partage et/ou sur réservation|Disponibilité d\'un vélo électrique d\'entreprise qui m\'est attribué en usage exclusif|Présence, dans l’entreprise, de râteliers et/ou d’espaces couverts et sécurisés pour le stationnement|Présence, dans l’entreprise, de bornes de recharge pour vélos électriques|Présence, dans l’entreprise, de casiers / douches / vestiaires dédiés|Présence, dans l’entreprise, de bornes de maintenance / réparation de vélos|Disponibilité d\'incitations économiques pour l\'achat du vélo|Attribution de récompenses et/ou de remboursements kilométriques pour l\'utilisation du vélo|Aucune condition, je ne suis pas disposé(e) à utiliser le vélo|Aucune condition, je suis dans l\'impossibilité d\'utiliser le vélo'],
			591 => ['À quelles conditions seriez-vous disposé(e) à changer vos habitudes pour les déplacements professionnels ?', '', 'Gratuité du service|Temps de trajet plus court par rapport à la voiture particulière|Moins de difficultés de stationnement par rapport à la voiture particulière|Service fréquent et disponible à toute heure|Service à domicile|Aucune condition, je ne suis pas intéressé(e)'],
			592 => ['Comment vous rendez-vous le plus souvent au travail ?', '', 'Réunions sur les stratégies de mobilité urbaine durable|Réunions de formation sur l\'offre de transport RER|Réunions d\'information sur les stratégies d\'entreprise pour le trajet domicile-travail|Moments de convivialité, visites guidées, balades à vélo, etc. sur le thème de la mobilité durable|Cours d\'Éco-Conduite|Communauté et Groupes pour l\'utilisation des différents services|Promotion de l’utilisation des transports en commun avec des facilités ou des abonnements d’entreprise|Projets « bike to work » avec incitations ou avantages|Services d’entreprise de bike sharing ou de trottinettes électriques partagées|Services de navette d’entreprise ou interentreprises vers les nœuds de transport en commun|Parkings d\'entreprise réservés à ceux qui pratiquent le covoiturage|Workshop sur le bien-être et la sécurité liés aux déplacements domicile-travail|Défis et récompenses pour ceux qui adoptent des modes durables|Guichets de conseil individuel sur la mobilité|Journées thématiques d\'entreprise (Bike Day, Mobility Day, Car Free Day)|Autre'],
			593 => ['Quels modes alternatifs utiliseriez-vous pour votre trajet domicile-travail ?', '', 'Réunions sur les stratégies de mobilité urbaine durable|Réunions de formation sur l\'offre de transport RER|Réunions d\'information sur les stratégies d\'entreprise pour le trajet domicile-travail|Moments de convivialité, visites guidées, balades à vélo, etc. sur le thème de la mobilité durable|Cours d\'Éco-Conduite|Communauté et Groupes pour l\'utilisation des différents services|Promotion de l’utilisation des transports en commun avec des facilités ou des abonnements d’entreprise|Projets « bike to work » avec incitations ou avantages|Services d’entreprise de bike sharing ou de trottinettes électriques partagées|Services de navette d’entreprise ou interentreprises vers les nœuds de transport en commun|Parkings d\'entreprise réservés à ceux qui pratiquent le covoiturage|Workshop sur le bien-être et la sécurité liés aux déplacements domicile-travail|Défis et récompenses pour ceux qui adoptent des modes durables|Guichets de conseil individuel sur la mobilité|Journées thématiques d\'entreprise (Bike Day, Mobility Day, Car Free Day)|Autre'],
			594 => ['% VOITURE', '', 'Réunions sur les stratégies de mobilité urbaine durable|Réunions de formation sur l\'offre de transport RER|Réunions d\'information sur les stratégies d\'entreprise pour le trajet domicile-travail|Moments de convivialité, visites guidées, balades à vélo, etc. sur le thème de la mobilité durable|Cours d\'Éco-Conduite|Communauté et Groupes pour l\'utilisation des différents services|Promotion de l’utilisation des transports en commun avec des facilités ou des abonnements d’entreprise|Projets « bike to work » avec incitations ou avantages|Services d’entreprise de bike sharing ou de trottinettes électriques partagées|Services de navette d’entreprise ou interentreprises vers les nœuds de transport en commun|Parkings d\'entreprise réservés à ceux qui pratiquent le covoiturage|Workshop sur le bien-être et la sécurité liés aux déplacements domicile-travail|Défis et récompenses pour ceux qui adoptent des modes durables|Guichets de conseil individuel sur la mobilité|Journées thématiques d\'entreprise (Bike Day, Mobility Day, Car Free Day)|Autre'],
			595 => ['% VÉLO', '', 'Réunions sur les stratégies de mobilité urbaine durable|Réunions de formation sur l\'offre de transport RER|Réunions d\'information sur les stratégies d\'entreprise pour le trajet domicile-travail|Moments de convivialité, visites guidées, balades à vélo, etc. sur le thème de la mobilité durable|Cours d\'Éco-Conduite|Communauté et Groupes pour l\'utilisation des différents services|Promotion de l’utilisation des transports en commun avec des facilités ou des abonnements d’entreprise|Projets « bike to work » avec incitations ou avantages|Services d’entreprise de bike sharing ou de trottinettes électriques partagées|Services de navette d’entreprise ou interentreprises vers les nœuds de transport en commun|Parkings d\'entreprise réservés à ceux qui pratiquent le covoiturage|Workshop sur le bien-être et la sécurité liés aux déplacements domicile-travail|Défis et récompenses pour ceux qui adoptent des modes durables|Guichets de conseil individuel sur la mobilité|Journées thématiques d\'entreprise (Bike Day, Mobility Day, Car Free Day)|Autre'],
			596 => ['Comment vous rendez-vous à l\'école ?', '', 'À pied (> 5min)|Vélo musculaire / électrique, cargo-bike ou trottinette|Transport en commun (bus, métro, train)|Partage du véhicule avec les collègues (car pooling)|Véhicule automobile ou motocyclette'],
			597 => ['Avec quel moyen de transport aimeriez-vous vous rendre à l\'école ?', '', 'Par choix ou organisation de l’entreprise|Par habitude (je n\'ai jamais envisagé ou essayé d\'alternatives)|Transport de matériaux ou d\'outils de travail|Parce que c’est le moyen de transport le plus rapide|Parce que c’est le seul moyen pour atteindre la destination|Pour le confort de voyage (ex. je ne suis pas dérangé(e) par d\'autres, frais en été et chaud en hiver, à l\'abri de la pluie, aucun trajet à pied, etc.)'],
