		// ──── Insert EN translations for Questions ────
		foreach ($questionsEn as $questionId => $fields) {
			$i18n->insert([
				['locale' => 'en', 'model' => 'Questions', 'foreign_key' => $questionId, 'field' => 'description', 'content' => $fields[0]],
				['locale' => 'en', 'model' => 'Questions', 'foreign_key' => $questionId, 'field' => 'long_description', 'content' => $fields[1]],
				['locale' => 'en', 'model' => 'Questions', 'foreign_key' => $questionId, 'field' => 'options', 'content' => $fields[2]],
			]);
		}
		$i18n->save();

		// ──── Insert FR translations for Questions ────
		foreach ($questionsFr as $questionId => $fields) {
			$i18n->insert([
				['locale' => 'fr', 'model' => 'Questions', 'foreign_key' => $questionId, 'field' => 'description', 'content' => $fields[0]],
				['locale' => 'fr', 'model' => 'Questions', 'foreign_key' => $questionId, 'field' => 'long_description', 'content' => $fields[1]],
				['locale' => 'fr', 'model' => 'Questions', 'foreign_key' => $questionId, 'field' => 'options', 'content' => $fields[2]],
			]);
		}
		$i18n->save();

		// ──── QuestionsSurveys translations ────
		// Look up questions_surveys IDs for all questions
		$questionIds = array_keys($questionsEn);
		$placeholders = implode(',', $questionIds);
		$rows = $this->fetchAll(
			"SELECT id, question_id, survey_id FROM questions_surveys WHERE question_id IN ($placeholders)"
		);

		// Insert EN for QuestionsSurveys
		foreach ($rows as $row) {
			$qid = (int)$row['question_id'];
			if (!isset($questionsEn[$qid])) {
				continue;
			}
			$fields = $questionsEn[$qid];
			$i18n->insert([
				['locale' => 'en', 'model' => 'QuestionsSurveys', 'foreign_key' => (int)$row['id'], 'field' => 'description', 'content' => $fields[0]],
				['locale' => 'en', 'model' => 'QuestionsSurveys', 'foreign_key' => (int)$row['id'], 'field' => 'long_description', 'content' => $fields[1]],
				['locale' => 'en', 'model' => 'QuestionsSurveys', 'foreign_key' => (int)$row['id'], 'field' => 'options', 'content' => $fields[2]],
			]);
		}
		$i18n->save();

		// Insert FR for QuestionsSurveys
		foreach ($rows as $row) {
			$qid = (int)$row['question_id'];
			if (!isset($questionsFr[$qid])) {
				continue;
			}
			$fields = $questionsFr[$qid];
			$i18n->insert([
				['locale' => 'fr', 'model' => 'QuestionsSurveys', 'foreign_key' => (int)$row['id'], 'field' => 'description', 'content' => $fields[0]],
				['locale' => 'fr', 'model' => 'QuestionsSurveys', 'foreign_key' => (int)$row['id'], 'field' => 'long_description', 'content' => $fields[1]],
				['locale' => 'fr', 'model' => 'QuestionsSurveys', 'foreign_key' => (int)$row['id'], 'field' => 'options', 'content' => $fields[2]],
			]);
		}
		$i18n->save();
	}
